const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const messages = [];
  page.on('console', msg => messages.push({ type: msg.type(), text: msg.text() }));
  page.on('pageerror', err => messages.push({ type: 'pageerror', text: err.message }));
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle', timeout: 60000 });
  await page.evaluate(async () => {
    for (const y of [300, 800, 1400, 2200, 3200, 4200]) {
      window.scrollTo({ top: y, behavior: 'auto' });
      await new Promise(r => setTimeout(r, 150));
    }
    window.scrollTo({ top: 0, behavior: 'auto' });
    await new Promise(r => setTimeout(r, 150));
  });
  await page.waitForTimeout(500);
  const bad = messages.filter(m => ['error', 'pageerror'].includes(m.type));
  console.log(`browser_console_total=${messages.length}`);
  console.log(`browser_console_errors=${bad.length}`);
  if (bad.length) console.log(JSON.stringify(bad, null, 2));
  await browser.close();
  process.exit(bad.length ? 1 : 0);
})().catch(err => { console.error(err.stack || err.message); process.exit(1); });

