const { spawn } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const candidates = [
  'C:/Program Files/Microsoft/Edge/Application/msedge.exe',
  'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
  'C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe'
];
const exe = candidates.find(p => fs.existsSync(p));
if (!exe) throw new Error('No Edge/Chrome executable found for CDP browser verification');
const port = 9333 + Math.floor(Math.random() * 500);
const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 's02-cdp-'));
const browser = spawn(exe, ['--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`, 'about:blank'], { stdio: 'ignore' });
function wait(ms){ return new Promise(r => setTimeout(r, ms)); }
async function getJson(url, tries=60) {
  let last;
  for (let i=0; i<tries; i++) {
    try { const r = await fetch(url); if (r.ok) return await r.json(); last = new Error(`HTTP ${r.status}`); }
    catch(e) { last = e; }
    await wait(250);
  }
  throw last;
}
(async () => {
  try {
    await getJson(`http://127.0.0.1:${port}/json/version`);
    const target = await (await fetch(`http://127.0.0.1:${port}/json/new?http://localhost:3000`)).json();
    const ws = new WebSocket(target.webSocketDebuggerUrl);
    let id = 0;
    const pending = new Map();
    const bad = [];
    const allConsole = [];
    ws.onmessage = ev => {
      const msg = JSON.parse(ev.data);
      if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
      if (msg.method === 'Runtime.exceptionThrown') bad.push({ type: 'exception', text: msg.params.exceptionDetails?.text || msg.params.exceptionDetails?.exception?.description || 'exception' });
      if (msg.method === 'Log.entryAdded') {
        const e = msg.params.entry; allConsole.push({ type: e.level, text: e.text });
        if (['error'].includes(e.level)) bad.push({ type: e.level, text: e.text });
      }
      if (msg.method === 'Runtime.consoleAPICalled') {
        const text = (msg.params.args || []).map(a => a.value || a.description || '').join(' ');
        allConsole.push({ type: msg.params.type, text });
        if (['error', 'assert'].includes(msg.params.type)) bad.push({ type: msg.params.type, text });
      }
    };
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
    const send = (method, params={}) => new Promise(resolve => { const msgId = ++id; pending.set(msgId, resolve); ws.send(JSON.stringify({ id: msgId, method, params })); });
    await send('Runtime.enable');
    await send('Log.enable');
    await send('Page.enable');
    await wait(3000);
    await send('Runtime.evaluate', { awaitPromise: true, expression: `(async () => { for (const y of [300,800,1400,2200,3200,4200]) { window.scrollTo({top:y, behavior:'auto'}); await new Promise(r => setTimeout(r, 180)); } window.scrollTo({top:0, behavior:'auto'}); await new Promise(r => setTimeout(r, 300)); return document.title + '|' + document.body.innerText.slice(0,80); })()` });
    await wait(1000);
    console.log(`browser_executable=${exe}`);
    console.log(`browser_console_total=${allConsole.length}`);
    console.log(`browser_console_errors=${bad.length}`);
    if (bad.length) console.log(JSON.stringify(bad, null, 2));
    ws.close();
    process.exit(bad.length ? 1 : 0);
  } finally {
    browser.kill('SIGTERM');
  }
})().catch(err => { console.error(err.stack || err.message); try { browser.kill('SIGTERM'); } catch {} process.exit(1); });

